class Solution {
public:
    int minimumSwaps(std::vector<int>& nums) {
        int n = nums.size();
        int min_idx = 0, max_idx = 0;
        for (int i = 0; i < n; ++i) {
            if (nums[i] < nums[min_idx]) min_idx = i;
            if (nums[i] >= nums[max_idx]) max_idx = i;
        }
        int swaps = min_idx + (n - 1 - max_idx);
        return min_idx > max_idx ? swaps - 1 : swaps;
    }
};

